package com.mmcafe.common.advice;
import com.mmcafe.common.api.ApiError; import com.mmcafe.common.exception.ResourceNotFoundException; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(ResourceNotFoundException.class) ResponseEntity<ApiError> notFound(ResourceNotFoundException e){ return ResponseEntity.status(404).body(ApiError.of(404,"NOT_FOUND",e.getMessage(),List.of())); } @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiError> bad(MethodArgumentNotValidException e){ var details=e.getBindingResult().getFieldErrors().stream().map(x->x.getField()+": "+x.getDefaultMessage()).toList(); return ResponseEntity.badRequest().body(ApiError.of(400,"BAD_REQUEST","Invalid request",details)); } }
